CREATE TABLE public.storage_slots (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    code character varying NOT NULL,
    shelf_id uuid NOT NULL,
    status character varying DEFAULT 'EMPTY'::character varying NOT NULL,
    lot_id character varying,
    lot_code character varying,
    product_sku character varying,
    max_weight_kg double precision DEFAULT '500'::double precision NOT NULL,
    current_weight_kg double precision DEFAULT '0'::double precision NOT NULL,
    "row" integer DEFAULT 1 NOT NULL,
    "position" integer DEFAULT 1 NOT NULL,
    is_priority boolean DEFAULT false NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL
